#!/usr/bin/env python3
"""Resolve effective guard-binding text across runners and command catalogs."""

from __future__ import annotations

from pathlib import Path


REPO_ROOT = Path(__file__).resolve().parents[2]

AUTORUN_PATH = "governance/compat/run_agent_autorun_workflow_gate.py"
HOOK_CHAIN_PATH = "governance/compat/run_local_governance_hook_chain.py"

CATALOG_PATHS_BY_RUNNER = {
    AUTORUN_PATH: (
        "governance/compat/agent_autorun_command_catalog.py",
    ),
    HOOK_CHAIN_PATH: (
        "governance/compat/local_governance_hook_catalog.py",
        "governance/compat/local_governance_hook_catalog_reviewer_fast.py",
        "governance/compat/local_governance_hook_catalog_pre_commit.py",
        "governance/compat/local_governance_hook_catalog_pre_push.py",
    ),
}


def normalize_path(path: str | Path) -> str:
    return str(path).replace("\\", "/")


def read_rel(path: str | Path) -> str:
    full = REPO_ROOT / normalize_path(path)
    if not full.exists() or full.is_dir():
        return ""
    return full.read_text(encoding="utf-8", errors="replace")


def effective_binding_text(path: str | Path, text: str | None = None) -> str:
    """Return the text a binding checker should inspect for a runner path.

    Runner files now delegate command definitions to catalog modules. A guard
    can be wired through those catalogs even when the runner no longer embeds
    the command literal directly.
    """
    normalized = normalize_path(path)
    parts = [text if text is not None else read_rel(normalized)]
    for catalog_path in CATALOG_PATHS_BY_RUNNER.get(normalized, ()):
        parts.append(read_rel(catalog_path))
    return "\n".join(parts)


def has_binding_marker(path: str | Path, marker: str, text: str | None = None) -> bool:
    return marker in effective_binding_text(path, text)


# Public distribution owns normative requirements, not provenance session or
# dispatch evidence. This explicit list is policy, never an exists() heuristic.
PRIVATE_BINDING_PATHS = frozenset({
    "CLAUDE.md", "CVF_SESSION_MEMORY.md",
    "governance/compat/run_agent_autorun_workflow_gate.py",
    "governance/compat/run_local_governance_hook_chain.py",
    "scripts/cvf_active_archive.py",
    "scripts/rotate_cvf_incremental_test_log.py",
    "scripts/rotate_cvf_conformance_trace.py",
})
PRIVATE_EVIDENCE_PREFIXES = (
    "CVF_SESSION/", "docs/baselines/", "docs/reviews/", "docs/roadmaps/",
    "docs/assessments/", "docs/audits/", "docs/reference/archive/", "roadmaps/",
)


def private_binding(path: str | Path) -> bool:
    normalized = normalize_path(path)
    return normalized in PRIVATE_BINDING_PATHS or normalized.startswith(PRIVATE_EVIDENCE_PREFIXES)


def public_required_paths(paths):
    """Select declared public requirements; absent public targets still fail."""
    return tuple(path for path in paths if not private_binding(path))


def public_required_markers(markers):
    return {
        path: tuple(marker for marker in values if not private_binding(marker))
        for path, values in markers.items() if not private_binding(path)
    }


def require_public_projection(root: Path) -> None:
    """An explicit profile cannot turn a private checkout into public scope."""
    source = root / "governance/toolkit/05_OPERATION/CVF_PUBLIC_CORE_AGENTS.md"
    carrier = root / "AGENTS.md"
    if not source.is_file() or not carrier.is_file() or source.read_bytes() != carrier.read_bytes():
        raise ValueError("public profile requires the exact exported public AGENTS carrier")


